use std::fs
use std::process

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    let mut width = 0
    let mut ok = false
    let mut cur = ""
    let mut curlen = 0
    let mut out: Vec<string> = []
    for line in text.lines() {
        if first {
            first = false
            match line.trim().parse::<int>() {
                Ok(n) => {
                    if n > 0 {
                        width = n
                        ok = true
                    }
                }
                Err(_) => {}
            }
            if !ok {
                println("error: bad width")
                process::exit(1)
            }
        } else {
            for w in line.split_whitespace() {
                let wl: int = w.chars().count() as int
                if curlen == 0 {
                    cur = w
                    curlen = wl
                } else if curlen + 1 + wl <= width {
                    cur = "${cur} ${w}"
                    curlen = curlen + 1 + wl
                } else {
                    out.push(cur)
                    cur = w
                    curlen = wl
                }
            }
        }
    }
    if first {
        println("error: bad width")
        process::exit(1)
    }
    if curlen > 0 {
        out.push(cur)
    }
    for l in out {
        println(l)
    }
}

